package com.configmonitor.app;

import android.app.Activity;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.os.*;
import android.view.*;
import android.webkit.*;
import android.widget.*;
import org.json.JSONObject;
import java.net.*;
import java.io.*;

/** Untrusted creatives live in their own WebView, never in the privileged app WebView. */
final class AdView extends LinearLayout {
 interface Listener { void available(boolean value); }
 final Activity activity;final String placement;final Listener listener;final Handler handler=new Handler(Looper.getMainLooper());
 JSONObject ad;WebView creative;GifBannerView gifBanner;Bitmap bannerBitmap;boolean active,disposed,ready,impressed,pending,loading;long visibleSince,nextAttempt;int generation;
 AdView(Activity activity,String placement,Listener listener){super(activity);this.activity=activity;this.placement=placement;this.listener=listener;setOrientation(VERTICAL);setPadding(dp(10),dp(6),dp(10),dp(8));frame();setClipToOutline(true);setVisibility(GONE);}
 int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 void frame(){boolean alarm="alarm".equals(placement),light=!alarm&&App.prefs.getString("theme","dark").equals("light");GradientDrawable bg=new GradientDrawable();bg.setColor(alarm?Color.rgb(31,17,20):light?Color.rgb(241,249,245):Color.rgb(14,25,20));bg.setCornerRadius(dp(18));bg.setStroke(dp(1),alarm?Color.rgb(76,37,44):light?Color.rgb(196,221,207):Color.rgb(42,69,55));setBackground(bg);}
 void start(){frame();active=true;if(gifBanner!=null)gifBanner.playing(true);handler.removeCallbacks(tick);handler.post(tick);}
 void stop(){active=false;if(gifBanner!=null)gifBanner.playing(false);visibleSince=0;handler.removeCallbacks(tick);if(creative!=null)creative.onPause();}
 void destroy(){disposed=true;generation++;stop();clear();}
 void clear(){generation++;loading=false;ready=false;impressed=false;pending=false;ad=null;setVisibility(GONE);if(creative!=null){creative.stopLoading();creative.destroy();creative=null;}if(gifBanner!=null){gifBanner.playing(false);gifBanner=null;}removeAllViews();if(bannerBitmap!=null){bannerBitmap.recycle();bannerBitmap=null;}if(listener!=null)listener.available(false);}
 final Runnable tick=new Runnable(){public void run(){if(!active||disposed)return;long now=System.currentTimeMillis();if(!Platform.enabled()){if(ad!=null)clear();}else if(ad==null&&!loading&&now>=nextAttempt)load();else if(ad!=null&&now>=ad.optLong("expires")*1000L){clear();nextAttempt=now+1000;}else if(ready&&!impressed&&!pending){Rect visible=new Rect();boolean enough=isShown()&&activity.hasWindowFocus()&&getGlobalVisibleRect(visible)&&(long)visible.width()*visible.height()>=(long)getWidth()*getHeight()/2&&getWidth()>0;Rect clip=getClipBounds();if(enough&&clip!=null&&clip.width()*clip.height()<getWidth()*getHeight()/2)enough=false;if(enough){if(visibleSince==0)visibleSince=now;if(now-visibleSince>=1100){pending=true;final JSONObject current=ad;Platform.event(ad.optString("id"),"impression",(r,e)->{if(ad!=current||disposed)return;pending=false;if(e==null)impressed=true;else visibleSince=System.currentTimeMillis()+4000;});}}else visibleSince=0;}handler.postDelayed(this,250);}};
 void load(){loading=true;nextAttempt=System.currentTimeMillis()+60000;final int token=++generation;Platform.ad(placement,(value,error)->{if(disposed||token!=generation)return;loading=false;if(value==null)return;ad=value;if("code".equals(value.optString("kind"))&&"main".equals(placement))loadCode(token);else loadBanner(token);});}
 void label(){TextView text=new TextView(activity);text.setText(App.t("تبلیغ","Advertisement"));text.setTextSize(10);text.setTextColor("alarm".equals(placement)?Color.rgb(185,148,154):Color.rgb(107,161,132));text.setTypeface(android.graphics.Typeface.createFromAsset(getResources().getAssets(),"fonts/Vazirmatn.ttf"));text.setGravity(Gravity.CENTER_VERTICAL|Gravity.END);addView(text,new LayoutParams(-1,dp(22)));}
 void shown(){if(disposed)return;ready=true;setVisibility(VISIBLE);if(listener!=null)listener.available(true);if(creative!=null&&active)creative.onResume();if(gifBanner!=null)gifBanner.playing(active);}
 void failed(int token){if(token==generation&&!disposed){clear();nextAttempt=System.currentTimeMillis()+60000;}}
 void loadBanner(int token){final String path="/media/"+ad.optString("banner");if(!path.matches("/media/[a-f0-9]{48}")){failed(token);return;}Platform.IO.execute(()->{Bitmap bitmap=null;HttpURLConnection c=null;try{c=(HttpURLConnection)new URL(Platform.origin()+path).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(10000);c.setReadTimeout(15000);if(c.getResponseCode()!=200)throw new IOException();byte[] bytes;try(InputStream in=c.getInputStream()){bytes=Platform.read(in,2097152);}if(BannerFormat.gif(bytes)){if(!BannerFormat.safeGif(bytes))throw new IOException();final Movie movie=Movie.decodeByteArray(bytes,0,bytes.length);if(movie==null||movie.width()<1||movie.height()<1)throw new IOException();handler.post(()->{if(disposed||token!=generation)return;label();gifBanner=new GifBannerView(activity,movie);gifBanner.setContentDescription(ad.optString("title",App.t("تبلیغ","Advertisement")));addView(gifBanner,new LayoutParams(-1,0,1));gifBanner.setOnClickListener(w->click(ad.optString("url")));shown();});return;}BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);if(o.outWidth<1||o.outHeight<1||(long)o.outWidth*o.outHeight>16000000)throw new IOException();o.inSampleSize=1;while(Math.max(o.outWidth,o.outHeight)/o.inSampleSize>1600)o.inSampleSize*=2;o.inJustDecodeBounds=false;bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);if(bitmap==null)throw new IOException();final Bitmap image=bitmap;handler.post(()->{if(disposed||token!=generation){image.recycle();return;}label();bannerBitmap=image;ImageView v=new ImageView(activity);v.setImageBitmap(image);v.setScaleType(ImageView.ScaleType.FIT_CENTER);v.setContentDescription(ad.optString("title",App.t("تبلیغ","Advertisement")));addView(v,new LayoutParams(-1,0,1));v.setOnClickListener(w->click(ad.optString("url")));shown();});}catch(Exception e){handler.post(()->failed(token));}finally{if(c!=null)c.disconnect();}});}
 void click(String target){if(!ready||!active||!impressed||!Platform.webUrl(target))return;final String id=ad.optString("id");Platform.event(id,"click",(r,e)->{if(!disposed&&e==null)Platform.openWeb(activity,target);});}
 void loadCode(int token){String origin=Platform.prefs().getString("creativeOrigin","");if(origin.isEmpty()||origin.equals(Platform.origin())){failed(token);return;}String url=origin+"/creative/"+ad.optString("id");label();creative=new WebView(activity);creative.setBackgroundColor(Color.TRANSPARENT);WebSettings s=creative.getSettings();s.setJavaScriptEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setDomStorageEnabled(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setMediaPlaybackRequiresUserGesture(true);s.setSupportMultipleWindows(true);if(Build.VERSION.SDK_INT>=26)s.setSafeBrowsingEnabled(true);android.webkit.CookieManager.getInstance().setAcceptThirdPartyCookies(creative,false);creative.setWebViewClient(new WebViewClient(){
 @Override public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){if(!r.isForMainFrame())return !"https".equals(r.getUrl().getScheme());if(r.hasGesture())click(r.getUrl().toString());return true;}
 @Override public void onPageFinished(WebView w,String u){if(token==generation&&u.equals(url))shown();}
 @Override public void onReceivedError(WebView w,WebResourceRequest r,WebResourceError e){if(r.isForMainFrame())failed(token);}
 @Override public void onReceivedHttpError(WebView w,WebResourceRequest r,WebResourceResponse e){if(r.isForMainFrame())failed(token);}
 });creative.setWebChromeClient(new WebChromeClient(){@Override public boolean onCreateWindow(WebView view,boolean dialog,boolean gesture,Message message){if(!gesture)return false;WebView popup=new WebView(activity);popup.getSettings().setJavaScriptEnabled(false);popup.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){click(r.getUrl().toString());w.post(w::destroy);return true;}});((WebView.WebViewTransport)message.obj).setWebView(popup);message.sendToTarget();handler.postDelayed(popup::destroy,5000);return true;}});addView(creative,new LayoutParams(-1,0,1));creative.loadUrl(url);handler.postDelayed(()->{if(token==generation&&!ready)failed(token);},20000);}
}
